const original = $input.first().json;
const message = original.body?.message ?? {};
const calls = message.toolCallList ?? message.toolWithToolCallList ?? message.toolCalls ?? [];
const wrapper = calls.find((item) => String(
  item.name ?? item.toolCall?.function?.name ?? item.function?.name ?? ''
).toLowerCase() === 'getslots') ?? calls[0] ?? {};
const toolCall = wrapper.toolCall ?? wrapper;
let args = toolCall.parameters ?? toolCall.function?.arguments ?? wrapper.parameters ?? wrapper.function?.arguments ?? {};
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch { throw new Error('GetSlots arguments are not valid JSON.'); }
}
const toolCallId = String(toolCall.id ?? wrapper.id ?? '');
const start = new Date(args.starttime);
const end = new Date(args.endtime);
if (!toolCallId) throw new Error('Vapi did not include a GetSlots tool-call ID.');
if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) {
  throw new Error('GetSlots requires valid ISO-8601 starttime and endtime values.');
}
return [{ json: {
  ...original,
  toolCallId,
  callId: String(message.call?.id ?? ''),
  starttime: start.toISOString(),
  endtime: end.toISOString(),
  timezone: 'America/Chicago'
} }];

// Slot rules, shared with the other booking checks in this workflow.
// Monday to Friday, 9:00 AM to 6:00 PM America/Chicago, in the future,
// and clear of every busy event on the calendar.
const TIME_ZONE = 'America/Chicago';
const OPEN_MINUTES = 9 * 60;
const CLOSE_MINUTES = 18 * 60;
const SLOT_MS = 30 * 60 * 1000;

const partFormatter = new Intl.DateTimeFormat('en-US', {
  timeZone: TIME_ZONE, weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
});
const displayFormatter = new Intl.DateTimeFormat('en-US', {
  timeZone: TIME_ZONE, weekday: 'long', month: 'long', day: 'numeric',
  hour: 'numeric', minute: '2-digit', hour12: true,
});

function local(date) {
  const p = Object.fromEntries(partFormatter.formatToParts(date)
    .filter(({ type }) => type !== 'literal')
    .map(({ type, value }) => [type, value]));
  return { day: `${p.year}-${p.month}-${p.day}`, weekday: p.weekday, minutes: Number(p.hour) * 60 + Number(p.minute) };
}

function eventDate(value) {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

// Cancelled, "show as free" and all-day events never block a slot (all-day
// entries here are reminders such as due dates, and the free/busy check this
// replaced ignored them too); neither does the event being moved, when named.
function busyTimes(events, ignoreEventId) {
  return events.map((event) => {
    if (!event || event.status === 'cancelled' || event.transparency === 'transparent') return null;
    if (ignoreEventId && event.id === ignoreEventId) return null;
    const start = eventDate(event.start?.dateTime);
    const end = eventDate(event.end?.dateTime);
    return start && end && end > start ? { start, end } : null;
  }).filter(Boolean);
}

function checkSlot(startValue, endValue, events, ignoreEventId = '', now = new Date()) {
  const start = new Date(startValue);
  const end = new Date(endValue);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) {
    return { slotFree: false, slotReason: 'The requested time could not be read.' };
  }
  if (events.some((event) => event && event.error)) {
    return { slotFree: false, slotReason: 'The calendar could not be checked right now.' };
  }
  if (start <= now) return { slotFree: false, slotReason: 'That time has already passed.' };
  const from = local(start);
  const to = local(end);
  if (from.weekday === 'Sat' || from.weekday === 'Sun') {
    return { slotFree: false, slotReason: 'Appointments are only available Monday to Friday.' };
  }
  if (from.day !== to.day || from.minutes < OPEN_MINUTES || to.minutes > CLOSE_MINUTES) {
    return { slotFree: false, slotReason: 'Appointments are only available from 9:00 AM to 6:00 PM Central time.' };
  }
  const clash = busyTimes(events, ignoreEventId).some((busy) => start < busy.end && end > busy.start);
  if (clash) return { slotFree: false, slotReason: 'That time is already taken.' };
  return { slotFree: true, slotReason: '' };
}

// Every free 30-minute slot that starts inside [fromMs, toMs), optionally only
// on one local day.
function openSlots(fromMs, toMs, events, onDay = '', now = new Date()) {
  const slots = [];
  for (let startMs = Math.ceil(fromMs / SLOT_MS) * SLOT_MS; startMs + SLOT_MS <= toMs; startMs += SLOT_MS) {
    const start = new Date(startMs);
    const end = new Date(startMs + SLOT_MS);
    if (onDay && local(start).day !== onDay) continue;
    if (checkSlot(start, end, events, '', now).slotFree) {
      slots.push({ startTime: start.toISOString(), endTime: end.toISOString(), display: displayFormatter.format(start) });
    }
  }
  return slots;
}

const request = $('Prepare GetSlots Request').first().json;
const events = $input.all().map(({ json }) => json);
const now = new Date();
const start = new Date(request.starttime);
const end = new Date(request.endtime);
const DAY_MS = 24 * 60 * 60 * 1000;
const MAX_LISTED = 12;
const list = (slots) => slots.slice(0, MAX_LISTED).map(({ display }) => display).join('; ') +
  (slots.length > MAX_LISTED ? '; and more after that' : '');

let result;
let availableSlots = [];
if (events.some((event) => event && event.error)) {
  result = 'The calendar could not be checked right now. Apologise and offer to have someone call the caller back.';
} else if (end - start <= 60 * 60 * 1000) {
  // One specific time: confirm it, or say why not and offer that day's open times.
  const verdict = checkSlot(start, end, events, '', now);
  if (verdict.slotFree) {
    availableSlots = [{ startTime: start.toISOString(), endTime: end.toISOString(), display: displayFormatter.format(start) }];
    result = 'The requested appointment time is available. You may proceed with booking.';
  } else {
    availableSlots = openSlots(start.getTime() - DAY_MS, start.getTime() + DAY_MS, events, local(start).day, now);
    result = verdict.slotReason + ' Do not book it. ' + (availableSlots.length
      ? 'Open 30-minute times that day: ' + list(availableSlots) + '.'
      : 'There are no open times that day, so ask the caller for another weekday.');
  }
} else {
  availableSlots = openSlots(start.getTime(), end.getTime(), events, '', now);
  result = availableSlots.length
    ? 'Available 30-minute appointment start times: ' + list(availableSlots) + '.'
    : 'No 30-minute appointment times are available in the requested range.';
}

return [{ json: { results: [{ toolCallId: request.toolCallId, result }], availableSlots } }];

// Notes reach Google Calendar as a plain field value, so they need no escaping.
// Escaping them here wrote literal backslashes into the event description.
for (const item of $input.all()) {
  item.json.notes = String(item.json.notes ?? '').trim();
}

return $input.all();

// Get all input items
const items = $input.all();

// Loop through each item
for (const item of items) {
  // Get the values from the current item's JSON data
  const startTimeUTC = item.json.starttime;
  const endTimeUTC = item.json.endtime;
  const targetTimeZone = item.json.timeZone; // e.g., "America/Chicago"

  // Basic validation: ensure the necessary fields exist
  if (!startTimeUTC || !endTimeUTC || !targetTimeZone) {
    console.warn(`Skipping item due to missing time data or timezone. Item JSON: ${JSON.stringify(item.json)}`);
    item.json.conversionError = "Missing starttime, endtime, or timeZone";
    continue; // Move to the next item
  }

  try {
    // --- Start Time Conversion ---
    // Parse the original UTC ISO string with Luxon, which n8n exposes as DateTime
    const startDt = DateTime.fromISO(startTimeUTC, { zone: 'utc' });

    // Convert the DateTime object to the target timezone
    const startDtTargetZone = startDt.setZone(targetTimeZone);

    // Check if the conversion was valid
    if (!startDtTargetZone.isValid) {
      throw new Error(`Failed to convert start time. Reason: ${startDtTargetZone.invalidReason || 'Unknown'}`);
    }

    // Format the result back into an ISO string with the correct offset
    item.json.starttime = startDtTargetZone.toISO();

    // --- End Time Conversion ---
    // Parse the original UTC ISO string with Luxon, which n8n exposes as DateTime
    const endDt = DateTime.fromISO(endTimeUTC, { zone: 'utc' });

    // Convert the DateTime object to the target timezone
    const endDtTargetZone = endDt.setZone(targetTimeZone);

     // Check if the conversion was valid
    if (!endDtTargetZone.isValid) {
      throw new Error(`Failed to convert end time. Reason: ${endDtTargetZone.invalidReason || 'Unknown'}`);
    }

    // Format the result back into an ISO string with the correct offset
    item.json.endtime = endDtTargetZone.toISO();

    // Optionally remove the error flag if conversion was successful this time
    delete item.json.conversionError;

  } catch (error) {
    console.error(`Error converting time for item: ${JSON.stringify(item.json)}. Error: ${error.message}`);
    // Add/update the error flag to the item's JSON
    item.json.conversionError = error.message;
  }
}
// Return the modified array of items
return items;

const original = $json;
const raw = original.error?.message ?? original.error?.description ?? original.message ?? 'Booking could not be completed.';
const text = String(raw);
const bookingMessage = text.includes('no_available_users_found_error')
  ? 'This time slot is no longer available.'
  : text;
return { json: { ...original, bookingMessage } };

const original = $json;

const body = original.body ?? {};
const message = body.message ?? {};

const calls =
  message.toolCallList ??
  message.toolWithToolCallList ??
  message.toolCalls ??
  [];

const wrapper = calls.find((item) =>
  String(
    item.name ??
    item.toolCall?.function?.name ??
    item.function?.name ??
    ''
  ).toLowerCase() === 'updateslots'
) ?? calls[0] ?? {};

const toolCall = wrapper.toolCall ?? wrapper;

let args =
  toolCall.parameters ??
  toolCall.function?.arguments ??
  wrapper.parameters ??
  wrapper.function?.arguments ??
  {};

if (typeof args === 'string') {
  args = JSON.parse(args);
}

const name = String(args.fullName ?? args.name ?? '').trim();
const email = String(args.email ?? '').trim().toLowerCase();

return {
  json: {
    ...original,

    Calls: calls,
    toolCallId: String(toolCall.id ?? wrapper.id ?? ''),
    call: {
      id: String(message.call?.id ?? ''),
    },

    name,
    fullName: name,
    email,
    customer_number: String(message.call?.customer?.number ?? ''),

    eventId: String(args.eventId ?? args.event_id ?? ''),
    starttime: String(args.starttime ?? ''),
    endtime: String(args.endtime ?? ''),

    Rescheduled_starttime: String(
      args.rescheduled_starttime ?? args.newStarttime ?? args.new_starttime ?? ''
    ),
    Rescheduled_endtime: String(
      args.rescheduled_endtime ?? args.newEndtime ?? args.new_endtime ?? ''
    ),
